import random,json,subprocess
R=random.Random(891723)
MAX=4611686018427387903
levels=['I','H','Z','A']

def config():
 return {'early':R.choice([True,False]),'overlap':R.choice(['first','reject']),
 'buffer_packets':R.randrange(5),'idle_ms':R.choice([0,1,3,10,100]),
 'max_streams_bidi':R.randrange(5),'max_streams_uni':R.randrange(5),
 'max_stream_data':R.randrange(20),'max_data':R.randrange(50),'crypto_limit':R.randrange(20),
 'sent':{x:[[0,3],[6,9]] for x in ['I','H','A']}}
def frame():
 k=R.choice(['PADDING','PING','ACK','CRYPTO','STREAM','RESET_STREAM','STOP_SENDING','CLOSE','HANDSHAKE_DONE','UNKNOWN'])
 if k in ['PADDING','PING','HANDSHAKE_DONE','UNKNOWN']: return {'type':k}
 if k=='ACK':
  rs=[]
  for _ in range(R.randrange(4)):
   a=R.randrange(12);b=R.randrange(12);rs.append([a,b])
  return {'type':'ACK','ranges':rs}
 if k=='CRYPTO': return {'type':k,'offset':R.randrange(25),'data_hex':R.randbytes(R.randrange(6)).hex()}
 if k=='STREAM': return {'type':k,'id':R.randrange(24),'offset':R.randrange(25),'data_hex':R.randbytes(R.randrange(6)).hex(),'fin':R.choice([True,False])}
 if k=='RESET_STREAM': return {'type':k,'id':R.randrange(24),'final_size':R.randrange(25)}
 if k=='STOP_SENDING': return {'type':k,'id':R.randrange(24)}
 return {'type':k,'app':R.choice([True,False]),'code':R.randrange(1000)}
def packet():
 return {'level':R.choice(levels),'pn':R.randrange(8),'auth':R.choice([True,True,False]),
 'frames':[frame() for _ in range(R.randrange(7))]}
def trace(i):
 es=[];t=0; arrivals=[]
 for e in range(R.randrange(25)):
  t+=R.randrange(4)
  op=R.choice(['datagram','datagram','key','tick'])
  if op=='tick':es.append({'t':t,'op':op})
  elif op=='key':es.append({'t':t,'op':op,'level':R.choice(levels),'action':R.choice(['install','discard'])})
  else:
   ps=[packet() for _ in range(R.randrange(1,5))]
   es.append({'t':t,'op':op,'bytes':R.choice([0,1199,1200,65535]),'packets':ps})
   arrivals.extend((len(es)-1,p) for p in range(len(ps)))
 return {'id':f't{i}','config':config(),'events':es},arrivals

for batch in range(100):
 ts=[];expected=[]
 for i in range(32):
  tr,a=trace(i);ts.append(tr);expected.append(a)
 req={'version':1,'traces':ts}
 p=subprocess.run(['python3','-I','/app/submission/entry.py'],input=json.dumps(req,separators=(',',':')).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 assert p.returncode==0,(batch,p.stderr)
 out=json.loads(p.stdout)
 assert 'error' not in out,(batch,out)
 for tr,r,a in zip(ts,out['results'],expected):
  assert len(r['packets'])==len(a)
  assert [(x['event'],x['packet']) for x in r['packets']]==a
  assert all(x['status'] in ['accepted','dropped','duplicate','buffered','error'] for x in r['packets'])
  assert all(x['reason'] is not None and x['at_ms'] is not None for x in r['packets'])
  assert r['received_total']==sum(s['highest'] for s in r['streams'])
  assert [s['id'] for s in r['streams']]==sorted(s['id'] for s in r['streams'])
  for s in r['streams']:
   assert len(s['delivered_hex'])%2==0 and len(s['delivered_hex'])//2<=s['highest']
   assert set(s)=={'id','highest','final_size','reset','stopped','delivered_hex'}
  assert [c['level'] for c in r['crypto']]==['I','H','A']
  for c in r['crypto']: assert len(c['contiguous_hex'])//2<=c['highest']
  co=r['connection']
  assert (co['state']=='open')==(co['code'] is None)
  assert (co['state']=='open')==(co['source'] is None)
print('100 randomized batches / 3200 traces passed')
